import{_ as i,o,c as a,ah as n}from"./chunks/framework.BVE8WBZz.js";const s="/projects/DaDablock/en/advanced-kit/assets/image1.BWTSxDiu.png",r="/projects/DaDablock/en/advanced-kit/assets/image2.DupOAC8G.png",e="/projects/DaDablock/en/advanced-kit/assets/image.DirOej9m.png",l="/projects/DaDablock/en/advanced-kit/assets/image4.QYSanSRd.png",c="/projects/DaDablock/en/advanced-kit/assets/image5.DzD53AtK.png",d="/projects/DaDablock/en/advanced-kit/assets/image1.gAgmRPNY.png",g="/projects/DaDablock/en/advanced-kit/assets/image2.B8zc0Jpr.png",A="/projects/DaDablock/en/advanced-kit/assets/image3.Bfu-hF-7.png",h="/projects/DaDablock/en/advanced-kit/assets/image4.Dpw6DOJM.png",p="/projects/DaDablock/en/advanced-kit/assets/image5.B8U9f3P-.png",m="/projects/DaDablock/en/advanced-kit/assets/image6.B3MpXkrF.png",w="/projects/DaDablock/en/advanced-kit/assets/image7.Co4TRYvD.png",k="/projects/DaDablock/en/advanced-kit/assets/image1.gNGP1QJQ.png",b="data:image/png;base64,",C="data:image/png;base64,",u="data:image/png;base64,",I="data:image/png;base64,",D="data:image/png;base64,",f="data:image/png;base64,",y="data:image/png;base64,",B="/projects/DaDablock/en/advanced-kit/assets/image9.CVWkDU6J.png",v="data:image/png;base64,",Q="data:image/png;base64,",E="/projects/DaDablock/en/advanced-kit/assets/image12.qT47jUn4.png",x="/projects/DaDablock/en/advanced-kit/assets/image13.-HsUBVdt.png",S="data:image/png;base64,",K="data:image/png;base64,",G="/projects/DaDablock/en/advanced-kit/assets/image1.CjIZMJTS.png",U="/projects/DaDablock/en/advanced-kit/assets/image2.B0YxKDNJ.png",R="/projects/DaDablock/en/advanced-kit/assets/image3.DJK6UrXx.png",V="/projects/DaDablock/en/advanced-kit/assets/image4.CslFUZqF.png",F="/projects/DaDablock/en/advanced-kit/assets/image5.CzVYFr8A.png",T="/projects/DaDablock/en/advanced-kit/assets/image2.BMzRBVLm.png",O="/projects/DaDablock/en/advanced-kit/assets/image3.DcdwK21P.png",q="/projects/DaDablock/en/advanced-kit/assets/image4.BJ7LQ1S2.png",M="/projects/DaDablock/en/advanced-kit/assets/image5.DMgbngzN.png",X=JSON.parse('{"title":"2. Quick Start Guide","description":"","frontmatter":{},"headers":[],"relativePath":"docs/2_Quick_Start_Guide.md","filePath":"docs/2_Quick_Start_Guide.md"}'),P={name:"docs/2_Quick_Start_Guide.md"};function z(J,t,H,j,Y,N){return o(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="_2-quick-start-guide" tabindex="-1">2. Quick Start Guide <a class="header-anchor" href="#_2-quick-start-guide" aria-label="Permalink to &quot;2. Quick Start Guide&quot;">​</a></h1><h2 id="_2-1-esp32-controller-overview" tabindex="-1">2.1 ESP32 Controller Overview <a class="header-anchor" href="#_2-1-esp32-controller-overview" aria-label="Permalink to &quot;2.1 ESP32 Controller Overview&quot;">​</a></h2><h3 id="_2-1-1-introduction" tabindex="-1">2.1.1 Introduction <a class="header-anchor" href="#_2-1-1-introduction" aria-label="Permalink to &quot;2.1.1 Introduction&quot;">​</a></h3><p>This is an intelligent controller built around ESP32 and supporting both block-based programming and Python programming. It uses a PC plastic housing and integrates onboard PWM servo ports, motor ports, programmable buttons, a buzzer, and other electronic modules. Multiple sensor ports are also provided for flexible expansion. All ports use a unified 4-pin anti-reverse connector design, making the controller compatible with the full Hiwonder sensor lineup while remaining convenient and safe to use.</p><img loading="lazy" height="1196" width="1743" src="'+s+'" class="inline-icon" style="width:400px;"><h3 id="_2-1-2-specifications" tabindex="-1">2.1.2 Specifications <a class="header-anchor" href="#_2-1-2-specifications" aria-label="Permalink to &quot;2.1.2 Specifications&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Item</th><th>Specification</th></tr></thead><tbody><tr><td>Product name</td><td>ESP32 controller</td></tr><tr><td>Dimensions</td><td>88.0 x 55.5 x 42.5 mm</td></tr><tr><td>Charging voltage</td><td>5 V</td></tr><tr><td>Charging current</td><td>1500 mA</td></tr><tr><td>Charging time</td><td>3.5 h</td></tr><tr><td>Battery capacity</td><td>Two 3.7 V, 1200 mAh lithium batteries</td></tr><tr><td>Maximum operating voltage</td><td>4.2 V</td></tr><tr><td>Rated operating voltage</td><td>3.7 V</td></tr></tbody></table><h3 id="_2-1-3-interface-overview" tabindex="-1">2.1.3 Interface Overview <a class="header-anchor" href="#_2-1-3-interface-overview" aria-label="Permalink to &quot;2.1.3 Interface Overview&quot;">​</a></h3><img loading="lazy" height="615" width="1018" src="'+r+'" class="inline-icon" style="width:700px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p><strong>S1-S4 are shared ports for block motors and servos, while P1-P8 are sensor ports.</strong></p></div><h3 id="_2-1-4-battery-charging-notes" tabindex="-1">2.1.4 Battery Charging Notes <a class="header-anchor" href="#_2-1-4-battery-charging-notes" aria-label="Permalink to &quot;2.1.4 Battery Charging Notes&quot;">​</a></h3><ol><li><p>Make sure the controller power switch is set to <strong>OFF</strong>. Install the battery in the battery compartment of the controller.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p><strong>Make sure the positive and negative terminals are not reversed.</strong></p></div><img loading="lazy" height="2001" width="2000" src="'+e+'" class="inline-icon" style="width:400px;"></li><li><p>Connect a USB data cable to the charging port on the controller, and connect the other end to a charger.</p><img loading="lazy" height="2000" width="2000" src="'+l+'" class="inline-icon" style="width:400px;"></li><li><p>While charging, the controller LED lights up blue. When charging is complete, the LED turns off. Disconnect the power cable promptly after charging to avoid overcharging.</p><img loading="lazy" height="785" width="933" src="'+c+'" class="inline-icon" style="width:400px;"></li></ol><h2 id="_2-2-wondercode-installation" tabindex="-1">2.2 WonderCode Installation <a class="header-anchor" href="#_2-2-wondercode-installation" aria-label="Permalink to &quot;2.2 WonderCode Installation&quot;">​</a></h2><ol><li><p>Open <strong><a href="https://www.hiwonder.net/pc-programming-software" target="_blank" rel="noreferrer">WonderCode setup.exe</a></strong>.</p><img loading="lazy" height="105" width="75" src="'+d+'" class="inline-icon" style="width:100px;border:1px solid black;"></li><li><p>Select the installation language, then click <strong>OK</strong>.</p><img loading="lazy" height="162" width="349" src="'+g+'" class="inline-icon" style="width:350px;border:1px solid black;"></li><li><p>Select the installation location, then click <strong>Next</strong>.</p><img loading="lazy" height="415" width="582" src="'+A+'" class="inline-icon" style="width:450px;border:1px solid black;"></li><li><p>Click <strong>Next</strong>.</p><img loading="lazy" height="415" width="582" src="'+h+'" class="inline-icon" style="width:450px;border:1px solid black;"></li><li><p>Click <strong>Install</strong>.</p><img loading="lazy" height="415" width="582" src="'+p+'" class="inline-icon" style="width:450px;border:1px solid black;"><img loading="lazy" height="415" width="582" src="'+m+'" class="inline-icon" style="width:450px;border:1px solid black;"></li><li><p>After the installation is complete, click <strong>Finish</strong>.</p><img loading="lazy" height="415" width="582" src="'+w+'" class="inline-icon" style="width:450px;border:1px solid black;"></li></ol><h2 id="_2-3-wondercode-overview" tabindex="-1">2.3 WonderCode Overview <a class="header-anchor" href="#_2-3-wondercode-overview" aria-label="Permalink to &quot;2.3 WonderCode Overview&quot;">​</a></h2><h3 id="_2-3-1-introduction" tabindex="-1">2.3.1 Introduction <a class="header-anchor" href="#_2-3-1-introduction" aria-label="Permalink to &quot;2.3.1 Introduction&quot;">​</a></h3><p>WonderCode is a Scratch-based programming tool for Hiwonder products. It supports automatic conversion between graphical blocks and Python code. Programs can be created by dragging and dropping blocks, making the software especially suitable for beginners learning programming.</p><h3 id="_2-3-2-programming-interface-overview" tabindex="-1">2.3.2 Programming Interface Overview <a class="header-anchor" href="#_2-3-2-programming-interface-overview" aria-label="Permalink to &quot;2.3.2 Programming Interface Overview&quot;">​</a></h3><p>The diagram below shows the functional areas of the <strong>WonderCode</strong> software: ① Menu Bar, ② Command Area, ③ Script Area, and ④ Code Display and Upload Area.</p><img loading="lazy" height="1040" width="1920" src="'+k+'" class="inline-icon" style="width:700px;"><p>The corresponding functions are listed in the table below:</p><table tabindex="0"><thead><tr><th>Icon</th><th>Function</th></tr></thead><tbody><tr><td><img loading="lazy" height="52" width="85" src="'+b+'" class="inline-icon" style="width:100px;"></td><td>Creates, saves, and opens program files.</td></tr><tr><td><img loading="lazy" height="53" width="89" src="'+C+'" class="inline-icon" style="width:100px;"></td><td>This section is used for online mode. It is included for reference only and is not required at this stage.</td></tr><tr><td><img loading="lazy" height="49" width="167" src="'+u+'" class="inline-icon" style="width:100px;"></td><td>Determines whether the device is connected to the software and selects the corresponding port.</td></tr><tr><td><img loading="lazy" height="49" width="103" src="'+I+'" class="inline-icon" style="width:100px;"></td><td>Used to access help information, check for updates, and install drivers.</td></tr><tr><td><img loading="lazy" height="51" width="217" src="'+D+'" class="inline-icon" style="width:100px;"></td><td>Displays the program file name. Before programming starts, or before a file is saved, the default name shown is <strong>Scratch Project</strong>.</td></tr><tr><td><img loading="lazy" height="48" width="261" src="'+f+'" class="inline-icon" style="width:100px;"></td><td>Switches the interface between online mode and upload mode.</td></tr><tr><td><img loading="lazy" height="42" width="56" src="'+y+'" class="inline-icon" style="width:100px;"></td><td>Selects the display language for the interface, including English, Simplified Chinese, and Traditional Chinese.</td></tr><tr><td><img loading="lazy" height="46" width="81" src="'+B+'" class="inline-icon" style="width:100px;"></td><td>Undoes or redoes actions while programming.</td></tr><tr><td><img loading="lazy" height="56" width="281" src="'+v+'" class="inline-icon" style="width:100px;"></td><td>Used to switch editing modes. <strong>Auto Conversion</strong> converts a block program into Python format, while <strong>Python Programming</strong> allows direct editing in Python.</td></tr><tr><td><img loading="lazy" height="45" width="49" src="'+Q+'" class="inline-icon" style="width:100px;"></td><td>Saves the current program as a Python file.</td></tr><tr><td><img loading="lazy" height="47" width="47" src="'+E+'" class="inline-icon" style="width:100px;"></td><td>Opens a previously saved Python file.</td></tr><tr><td><img loading="lazy" height="45" width="52" src="'+x+'" class="inline-icon" style="width:100px;"></td><td>Communicates with the device and downloads the program to the controller.</td></tr><tr><td><img loading="lazy" height="50" width="61" src="'+S+'" class="inline-icon" style="width:100px;"></td><td>Adds extension packages for devices.</td></tr><tr><td><img loading="lazy" height="156" width="67" src="'+K+'" class="inline-icon" style="width:100px;"></td><td>From top to bottom, these controls are used to zoom in, zoom out, and restore the default size of the code editing area.</td></tr></tbody></table><h2 id="_2-4-programming-steps" tabindex="-1">2.4 Programming Steps <a class="header-anchor" href="#_2-4-programming-steps" aria-label="Permalink to &quot;2.4 Programming Steps&quot;">​</a></h2><ol><li><strong>Open the software</strong>: Start the programming software and create a new project.</li></ol><img loading="lazy" height="879" width="1590" src="'+G+'" class="inline-icon" style="width:700px;"><ol start="2"><li><strong>Add the extension</strong></li></ol><ul><li>Open the <strong>Choose an Extension</strong> interface by clicking the icon in the lower-left corner of the software.</li></ul><img loading="lazy" height="879" width="1590" src="'+U+'" class="inline-icon" style="width:700px;"><ul><li>In <strong>Choose an Extension</strong>, choose <strong>Controller</strong> and add <strong>K12 ESP32</strong>.</li></ul><img loading="lazy" height="879" width="1590" src="'+R+'" class="inline-icon" style="width:700px;"><ul><li>After the extension is added successfully, the added package appears in the WonderCode interface.</li></ul><img loading="lazy" height="879" width="1590" src="'+V+'" class="inline-icon" style="width:700px;"><ol start="3"><li><strong>Write the program</strong>: Drag the required blocks from the command area into the script area to create the program. After the program is completed, the converted Python code appears in the code display and upload area.</li></ol><img loading="lazy" height="879" width="1590" src="'+F+'" class="inline-icon" style="width:700px;"><h2 id="_2-5-program-download-steps" tabindex="-1">2.5 Program Download Steps <a class="header-anchor" href="#_2-5-program-download-steps" aria-label="Permalink to &quot;2.5 Program Download Steps&quot;">​</a></h2><h3 id="_2-5-1-connecting-to-a-computer" tabindex="-1">2.5.1 Connecting to a Computer <a class="header-anchor" href="#_2-5-1-connecting-to-a-computer" aria-label="Permalink to &quot;2.5.1 Connecting to a Computer&quot;">​</a></h3><ol><li><p>Set the controller power switch to <strong>ON</strong>, then connect a USB data cable to the program download port on the controller.</p><img loading="lazy" height="2001" width="2000" src="'+e+'" class="inline-icon" style="width:400px;"></li><li><p>Plug the other end of the cable into a USB port on the computer.</p><img loading="lazy" height="432" width="357" src="'+T+'" class="inline-icon" style="width:200px;"></li><li><p>Click <strong>Connect</strong> and select the corresponding port.</p><img loading="lazy" height="144" width="441" src="'+O+'" class="inline-icon" style="width:400px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p><strong>The port number is not fixed. The example in this section uses COM3, but COM1 should not be selected because it is usually reserved for system communication. If multiple COM ports are shown and the correct one is unclear, right-click This PC, select Properties &gt; Device Manager, and check the port assigned to the controller. The correct port typically includes the CH340 identifier.</strong></p></div></li></ol><img loading="lazy" height="129" width="240" src="'+q+'" class="inline-icon" style="width:350px;"><h3 id="_2-5-2-downloading-the-program" tabindex="-1">2.5.2 Downloading the Program <a class="header-anchor" href="#_2-5-2-downloading-the-program" aria-label="Permalink to &quot;2.5.2 Downloading the Program&quot;">​</a></h3><p>Click the <strong>Download</strong> button in the upper-right corner to download the program to the controller.</p><img loading="lazy" height="1040" width="1920" src="'+M+'" class="inline-icon" style="width:700px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p><strong>If no COM port appears after the controller is connected, check whether the USB cable is a data cable, or try another USB data port on the computer.</strong></p></div>',42)])])}const Z=i(P,[["render",z]]);export{X as __pageData,Z as default};
